/* @autogenerated */
import { TemplateRef } from '@angular/core';
import { LocalRouteDirective } from './local-route.directive';

describe('LocalRouteDirective', () => {
  it('detects fallback and initial flags', () => {
    const directive = new LocalRouteDirective({} as TemplateRef<any>);

    directive.fallback = 'true';
    directive.initial = true;

    expect(directive.isFallback()).toBeTrue();
    expect(directive.isInitial()).toBeTrue();
  });
});
